mapper.select:
SELECT s.store_id AS storeId, s.material_id AS materialId, m.material_code AS materialCode, m.material_name AS materialName, m.unit AS unit, s.stock_qty AS stockQty, m.warn_threshold AS warnThreshold, (m.warn_threshold - s.stock_qty) AS gap FROM inv_store_material_stock s JOIN bom_material m ON m.id = s.material_id WHERE m.warn_threshold IS NOT NULL AND s.stock_qty < m.warn_threshold
AND s.store_id = #{storeId}
ORDER BY gap DESC, s.store_id, m.material_code
